<?php require_once 'inc/auth.php';require_once '../config/koneksi.php';$title='Lamaran Karier';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=$_POST['status']??'Baru';$allowed=['Baru','Diproses','Diterima','Ditolak'];if(in_array($status,$allowed,true)){$s=$conn->prepare('UPDATE career_applications SET status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute();}header('Location: career_applications.php');exit;}$rows=$conn->query("SELECT a.*,c.posisi FROM career_applications a LEFT JOIN career_positions c ON c.id=a.career_id ORDER BY a.id DESC");include 'inc/header.php';?><div class="page-title"><div><p class="eyebrow-admin">RECRUITMENT</p><h1>Lamaran Karier</h1><p>Review kandidat yang melamar melalui website.</p></div></div><div class="table-wrap"><table class="table"><tr><th>Kandidat</th><th>Posisi</th><th>Kontak</th><th>CV</th><th>Profil</th><th>Pesan</th><th>Status</th></tr><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><b><?=htmlspecialchars($r['nama'])?></b></td><td><?=htmlspecialchars($r['posisi']??'-')?></td><td><?=htmlspecialchars($r['email'])?><br><?=htmlspecialchars($r['no_hp'])?></td><td><?php if($r['cv']):?><a class="btn btn-small green" target="_blank" href="../uploads/cv/<?=htmlspecialchars($r['cv'])?>">Lihat CV</a><?php else:?>-<?php endif;?></td><td><a class="btn btn-small gray" href="candidate.php?id=<?= (int)$r['user_id']?>">Lihat Profil</a></td><td><?=htmlspecialchars($r['pesan']??'-')?></td><td><form method="post" class="inline-form"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><option <?=$r['status']==='Baru'?'selected':''?>>Baru</option><option <?=$r['status']==='Diproses'?'selected':''?>>Diproses</option><option <?=$r['status']==='Diterima'?'selected':''?>>Diterima</option><option <?=$r['status']==='Ditolak'?'selected':''?>>Ditolak</option></select></form></td></tr><?php endwhile;else:?><tr><td colspan="7" class="empty">Belum ada lamaran.</td></tr><?php endif;?></table></div><?php include 'inc/footer.php';?>
